import{_ as l,c as a,o,b0 as r}from"./chunks/framework.Dmsv_Tiv.js";const i="/media-docs/assets/20160516164141047.BIKWVDwf.jpg",t="/media-docs/assets/20160516164454535.BwD93XcA.jpg",b=JSON.parse('{"title":"LV010-H264的profile与level","description":null,"frontmatter":{"title":"LV010-H264的profile与level","date":"2025-12-09T20:25:12.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/vcodec/h264/126b1a217b502c775cdbdf0f","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-12-09T20:25:12.711Z","fulluuid":"75cdbdf0f28f40a78e7a63cd1930fbdf","useduuid":"75cdbdf0f"}},"headers":[],"relativePath":"sdoc/vcodec/h264/126b1a217b502c775cdbdf0f.md","filePath":"sdoc/20-视频编解码/20-H264/LV010-H264的profile与level.md","lastUpdated":1767537778000}'),p={name:"sdoc/vcodec/h264/126b1a217b502c775cdbdf0f.md"};function n(f,e,d,s,c,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="lv010-h264的profile与level" tabindex="-1">LV010-H264的profile与level <a class="header-anchor" href="#lv010-h264的profile与level" aria-label="Permalink to &quot;LV010-H264的profile与level&quot;">​</a></h1><p>一些移动设备（手机、游戏机、PMP）由于性能有限，不支持全部高级视频压缩特性和高分辨率图像，只支持基础压缩特性和分辨率低一些的图像。为了让这个限制更加清晰明了，H264 从低到高划分了很多 Profile 和 Level，设备只需要标出所支持的 Profile 和 Level 就可以让用户和开发者一看既知。</p><p>profile 主要是定义了编码工具的集合，不同的 profile，包含了不同的编码技术；而 level 主要是对码流的关键参数的取值范围作了限定，与解码器的处理能力和存储能力相关联。下面就来看一看这两个属性吧。</p><h2 id="一、h264——profile" tabindex="-1">一、H264——profile <a class="header-anchor" href="#一、h264——profile" aria-label="Permalink to &quot;一、H264——profile&quot;">​</a></h2><h3 id="_1-profile-是什么" tabindex="-1">1. profile 是什么？ <a class="header-anchor" href="#_1-profile-是什么" aria-label="Permalink to &quot;1. profile 是什么？&quot;">​</a></h3><p>Profile 是对视频压缩特性的描述（CABAC 呀、颜色采样数等等）。</p><blockquote><p>简单来说，Profile 越高，就说明采用了越高级的压缩特性。</p></blockquote><h3 id="_2-四种画质" tabindex="-1">2. 四种画质 <a class="header-anchor" href="#_2-四种画质" aria-label="Permalink to &quot;2. 四种画质&quot;">​</a></h3><p>H.264 有四种画质级别，分别是 baseline, extended, main, high：</p><ul><li><p>（1）Baseline Profile：基本画质。支持 I/P 帧，只支持无交错（Progressive）和 CAVLC。一般用于低阶或需要额外容错的应用，比如视频通话、手机视频等。</p></li><li><p>（2）Extended profile：进阶画质。支持 I/P/B/SP/SI 帧，只支持无交错（Progressive）和 CAVLC；(用的少)</p></li><li><p>（3）Main profile：主流画质。提供 I/P/B 帧，支持无交错（Progressive）和交错（Interlaced）， 也支持 CAVLC 和 CABAC。用于主流消费类电子产品规格如低解码（相对而言）的 mp4、便携的视频播放器、PSP 和 Ipod 等。</p></li><li><p>（4）High profile：高级画质。在 main Profile 的基础上增加了 8x8 内部预测、自定义量化、 无损视频编码和更多的 YUV 格式。用于广播及视频碟片存储（蓝光影片），高清电视的应用。</p></li></ul><p>简单来说，Profile 越高，就说明采用了越高级的压缩特性。我们可以看下面这个图，它给出了不同的 profile 的性能区别：</p><img src="'+i+'"><blockquote><p>Tips：</p><p>（1）H.264 Baseline profile、Extended profile 和 Main profile 都是针对 8 位样本数据、4:2:0 格式(YUV)的视频序列。</p><p>（2）根据应用领域的不同，Baseline profile 多应用于实时通信领域，Main profile 多应用于流媒体领域，High profile 则多应用于广电和存储领域。</p><p>（3）在相同配置情况下，High profile（HP）可以比 Main profile（MP）降低 10%的码率。</p></blockquote><h2 id="二、h264——level" tabindex="-1">二、H264——level <a class="header-anchor" href="#二、h264——level" aria-label="Permalink to &quot;二、H264——level&quot;">​</a></h2><h3 id="_1-level-是什么" tabindex="-1">1. level 是什么？ <a class="header-anchor" href="#_1-level-是什么" aria-label="Permalink to &quot;1. level 是什么？&quot;">​</a></h3><p>Level 是对视频本身特性的描述（码率、分辨率、fps）。</p><blockquote><p>Level 越高，视频的码率、分辨率、fps 越高。</p></blockquote><h3 id="_2-level-级别" tabindex="-1">2. level 级别 <a class="header-anchor" href="#_2-level-级别" aria-label="Permalink to &quot;2. level 级别&quot;">​</a></h3><img src="'+t+'"><blockquote><p>参考资料</p><p><a href="https://blog.csdn.net/qq_28258885/article/details/118890413" target="_blank" rel="noreferrer">H.264——H.264 的 profile 和 level_h264 profile level-CSDN 博客</a></p><p><a href="https://www.cnblogs.com/tinywan/p/6402007.html" target="_blank" rel="noreferrer">H264 编码 profile &amp; level 控制 - Tinywan - 博客园</a></p></blockquote>',20)])])}const v=l(p,[["render",n]]);export{b as __pageData,v as default};
